public String utpb(int val){
  String res = "";
  while( val > 0 ){
    int d = val % 10;
    val = val / 10;
    switch (d) {
      case 1: res += "A"; break;
      case 3: res += "BA"; break;
      case 5: res += "AA"; break;
      default:
        res += "C";
        val = val * 10 + 1;
    }
  }
  return res;
}

